/**
 * Project data model.
 *
 * Every project is a plain object of this shape (see data/projects/<slug>/index.ts).
 * The UI only depends on these types, so the source can later move from files to
 * a database (e.g. Supabase) without touching the components — see docs/projects-cms.md.
 */

export type Localized<T = string> = { ar: T; en: T };

/** A pre-processed image (generated by `npm run project-media`). */
export type MediaAsset = {
  src: string;
  width: number;
  height: number;
  /** Brochure page the image comes from */
  page?: number;
};

export type ProjectMedia = MediaAsset & {
  alt: Localized;
  caption?: Localized;
  /** "contain" for drawings that must not be cropped (sections, 3D cut-outs) */
  fit?: "cover" | "contain";
};

export type ProjectStatus = "draft" | "published";

export type FloorGroupId = "basements" | "commercial" | "residential" | "technical";

export type ProjectUnit = {
  /** Unit number exactly as printed in the brochure */
  number: string;
  /** Area in m² as printed in the brochure */
  area: number;
  type: "apartment" | "duplex";
};

export type ProjectFloor = {
  id: string;
  /** Vertical position: negative = basements, 0 = ground */
  level: number;
  /** Compact label for the building diagram / chips, e.g. "B4", "G", "12" */
  short: Localized;
  label: Localized;
  group: FloorGroupId;
  plan2d?: ProjectMedia;
  plan3d?: ProjectMedia;
  description?: Localized;
  parking?: number;
  units?: ProjectUnit[];
  /** Unit count as written in the floor heading (may differ from the listed units) */
  statedUnitCount?: number;
  pdfPages: number[];
};

export type ProjectFact = {
  value: string;
  label: Localized;
  detail?: Localized;
  /** Where the figure appears in the source document */
  pdfPage: number;
};

export type ProjectChapter = {
  id: string;
  eyebrow: Localized;
  title: Localized;
  body: Localized<string[]>;
  media: ProjectMedia;
  /** "photo" fills its frame; "cutout" is a transparent drawing shown on a tinted panel */
  mediaStyle?: "photo" | "cutout";
};

export type ProjectDocument = {
  id: string;
  title: Localized;
  /** Public path of the original file */
  file: string;
  sizeBytes: number;
  pageCount: number;
  language: "ar" | "en";
  cover: ProjectMedia;
};

export type Project = {
  slug: string;
  status: ProjectStatus;
  /** Lower first */
  order: number;
  featured: boolean;

  name: Localized;
  /** Plot / tower reference, e.g. "T104 / T105" */
  code?: string;
  type: Localized;
  /** Only set when confirmed */
  location?: Localized;
  /** Construction status as confirmed by the company */
  progress?: Localized;
  tagline: Localized;
  summary: Localized;
  /** Small note shown with the imagery (e.g. renderings may differ from the final build) */
  imageryNote?: Localized;

  hero: ProjectMedia;
  card: ProjectMedia;
  highlights: ProjectFact[];
  facts: ProjectFact[];
  chapters: ProjectChapter[];
  site?: {
    title: Localized;
    text: Localized;
    plan: ProjectMedia;
    panorama?: ProjectMedia;
  };
  gallery: ProjectMedia[];
  floorGroups: { id: FloorGroupId; label: Localized }[];
  floors: ProjectFloor[];
  floorsNote?: Localized;
  documents: ProjectDocument[];
};
